import{_ as i,o as n,c as t,a5 as h}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"FR 3.5.5 — Tự tạo Campaign DRAFT từ gói workspace","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-5-create-media-campaign/spec.md","filePath":"feature/media-package-campaign/3-5-5-create-media-campaign/spec.md"}'),e={name:"feature/media-package-campaign/3-5-5-create-media-campaign/spec.md"};function c(r,a,g,o,p,s){return n(),t("div",null,[...a[0]||(a[0]=[h('<h1 id="fr-3-5-5-—-tu-tao-campaign-draft-tu-goi-workspace" tabindex="-1">FR 3.5.5 — Tự tạo Campaign DRAFT từ gói workspace <a class="header-anchor" href="#fr-3-5-5-—-tu-tao-campaign-draft-tu-goi-workspace" aria-label="Permalink to &quot;FR 3.5.5 — Tự tạo Campaign DRAFT từ gói workspace&quot;">​</a></h1><p>Cập nhật BA 2026-11-05, chờ triển khai. Theo <a href="./../guest-sharing-manager-led/spec.html">spec hành trình mới</a> và <a href="./../../package-driven-campaign-tasks/spec.html">package-driven task</a>.</p><h2 id="muc-tieu" tabindex="-1">Mục tiêu <a class="header-anchor" href="#muc-tieu" aria-label="Permalink to &quot;Mục tiêu&quot;">​</a></h2><p>Manager lưu gói workspace hợp lệ sẽ có ngay một Campaign DRAFT và task lớn để chuẩn bị thực hiện. Campaign mô tả kế hoạch triển khai của gói đã chốt bên ngoài hệ thống.</p><h2 id="tieu-chi-nghiem-thu" tabindex="-1">Tiêu chí nghiệm thu <a class="header-anchor" href="#tieu-chi-nghiem-thu" aria-label="Permalink to &quot;Tiêu chí nghiệm thu&quot;">​</a></h2><ul><li>Tạo workspace chỉ cần Owner/gán Manager theo quy tắc tổ chức, chưa cần Client hoặc Package approval.</li><li>Lần lưu gói workspace hợp lệ đầu tiên tự tạo đúng một Campaign DRAFT cùng task theo dịch vụ/sản lượng của gói.</li><li>Lưu lại/retry/concurrent save sử dụng cùng Campaign/workspace và các định danh task ổn định.</li><li>Campaign/task giữ nguồn gói, liên kết workspace và các dữ liệu cần cho kế hoạch, tổng sản lượng, strategy, timeline và work items hiện hành.</li><li>Manager hoàn thiện các trường còn thiếu sau khi tạo DRAFT. Chỉ ra trường thiếu khi kiểm tra sẵn sàng triển khai.</li><li>Task có thể được chuẩn bị brief, deadline, assignee, supervisor, subtask trong giai đoạn DRAFT. Bắt đầu thực hiện vẫn yêu cầu Campaign IN_PROGRESS.</li><li>Cho phép Manager sửa gói trước triển khai, đồng bộ kế hoạch/task và giữ thông tin đã nhập. Thay đổi ảnh hưởng task phải theo quy tắc đồng bộ an toàn của spec mới.</li><li>Client được mời sau đó xem và góp ý cả bản nháp. Bình luận không làm thay đổi version nội dung kế hoạch hoặc đóng vai trò approval.</li><li>Một workspace có tối đa một Campaign. Chiến dịch mới dùng workspace mới theo quy tắc hiện hành.</li><li>Loading/error/empty/permission/conflict states, key vi/en và light/dark được thiết kế tương ứng.</li></ul><h2 id="tinh-nhat-quan" tabindex="-1">Tính nhất quán <a class="header-anchor" href="#tinh-nhat-quan" aria-label="Permalink to &quot;Tính nhất quán&quot;">​</a></h2><p>Campaign/work items và Mongo Task phải giữ cùng phạm vi gói. Retry không tạo task/Campaign trùng. Nếu ghi một phần thất bại, hệ thống phải thể hiện trạng thái chưa sẵn sàng và phục hồi có kiểm soát trước triển khai.</p><p>Các trường/version dùng để chống ghi đè vẫn có thể cần thiết. Không dùng approval hai phía làm điều kiện lưu, đồng bộ hoặc tạo Campaign. Dữ liệu/code/schema hiện tại sẽ được đánh giá ở bước plan.</p>',9)])])}const u=i(e,[["render",c]]);export{m as __pageData,u as default};
